using System;using System.Linq;
public sealed class Feature:IFeature {
 readonly AimDrive drive=new AimDrive();long previous,context,soldier,vehicle;int seat,stable;bool paused,lastF8,lastF9,headOverride;public void Stop(){drive.CancelPending();previous=0;stable=0;}public void Dispose(){}
 public string Tick(Frame f){if(!f.Focus){Stop();return "自动瞄准暂停：游戏不在前台";}var c=f.Input.config;bool f8=Native.Down(0x77),f9=Native.Down(0x78);if(f8&&!lastF8)paused=!paused;if(f9&&!lastF9)headOverride=!headOverride;lastF8=f8;lastF9=f9;if(Native.Down(0x1b)||Native.Down(0x0d))paused=true;if(paused){Stop();return "自动瞄准已暂停，按F8恢复";}bool head=(Values.Text(c,"mode","body")=="head")^headOverride;int radius=Values.Number(c,"radius",12),strength=Values.Number(c,"strength",55);if(radius<2||radius>90||strength<5||strength>100)throw new Exception("瞄准参数超出范围");var scene=f.Scene(head,false,100,Values.Flag(c,"excludeHumans",true));if(!scene.Ready){Stop();return scene.Status;}if(context!=scene.Context||soldier!=scene.LocalSoldier||vehicle!=scene.LocalVehicle||seat!=scene.VehicleSeat){context=scene.Context;soldier=scene.LocalSoldier;vehicle=scene.LocalVehicle;seat=scene.VehicleSeat;drive.Reset();Stop();}drive.Observe(scene,f.Now,Native.Down(1));var target=AimMath.Choose(scene.Targets,radius,previous);if(target==null){Stop();return "范围内没有可见目标";}stable=previous==target.Pointer?stable+1:1;previous=target.Pointer;var trigger=Values.Text(c,"trigger","ads");if(Native.Down(4)||!AimMath.TriggerHeld(trigger,Native.Down(1),Native.Down(2)))return "已就绪，按住所选鼠标键瞄准";if(stable>=2){int dx,dy;drive.Step(target,scene,strength,f.Now,out dx,out dy);if(!Native.Move(dx,dy,f.Reader.M.Process.Id,trigger))return "鼠标输入未送达";if(dx!=0||dy!=0)drive.Sent(scene,f.Now,dx,dy);}return "正在瞄准："+target.Name;}
 public static void Test(){var c=new System.Collections.Generic.List<Candidate>{new Candidate{Pointer=1,Angle=4},new Candidate{Pointer=2,Angle=2}};if(AimMath.Choose(c,3,0).Pointer!=2||AimDrive.Duration(100)!=0)throw new Exception("Aim math");}
}
